ruleToc.chapterList:
+<js>
var path="ul.list.0@li";
var path1="ul.list.1@li",
li=java.getElements(path),
lb=java.getElements(path1);
bid=baseUrl.match(/(\d+).?$/)[1];
call=src.match(/var callback='(.+?)'/)[1]
bse=java.webView(null,baseUrl,
	"base64(callback)");
	url=book.origin+`/?c=xs&a=list.json&callback=${call}&book_id=${bid}&b=${bse}`;
	head={"Referer":baseUrl};
get=java.get(url,head).body();
//java.log(get)
to=String(get).replace(/^\w+.|.;?$/g,"");
co=JSON.parse(to).content;
la=org.jsoup.Jsoup.parse(co).select('li');
//java.log(la)
li+la+lb;
</js>
